// Real data from api.daily.dev: the four directory lists exactly as
// production ranks them, sourcesByTag for every tag the categories use,
// each source's three latest posts, and per category its Squads and the
// developers writing about it. Fetched 2026-10-12, categories 2026-10-18.
// Regenerate rather than hand-edit.

export interface RawSource {
  id: string;
  handle: string;
  name: string;
  type: 'machine' | 'squad' | 'user';
  image: string;
  description: string | null;
  followers: number;
  createdAt: string;
  upvotes: number;
  posts: number;
  views: number;
}

export interface RawPost {
  id: string;
  title: string;
  image: string;
  createdAt: string;
  readTime: number | null;
  upvotes: number;
  comments: number;
  type: string;
  tags: string[];
}

export interface RawSquad {
  id: string;
  handle: string;
  name: string;
  image: string;
  members: number;
  description: string | null;
}

export interface RawPerson {
  id: string;
  name: string;
  username: string;
  image: string;
  bio: string | null;
  reputation: number;
}

